/** 
 * Returns a new  {@code Future} whose result is the product of applying thegiven  {@code Function} to the result of the given {@code Future}. <p>An example use of this method is to convert a Future that produces a handle to an object to a future that produces the object itself. <p>Each call to  {@code Future<O>.get(*)} results in a call to{@code Future<I>.get(*)}, but  {@code function} is only applied once, so itis assumed that  {@code Future<I>.get(*)} is idempotent.<p>When calling  {@link Future#get(long,TimeUnit)} on the returnedfuture, the timeout only applies to the future passed in to this method. Any additional time taken by applying  {@code function} is not considered.
 * @param future The future to compose
 * @param function A Function to compose the results of the provided futureto the results of the returned future.  This will be run in the thread that calls one of the varieties of  {@code get()}.
 * @return A future that computes result of the composition.
 */
public static <I,O>Future<O> compose(final Future<I> future,final Function<? super I,? extends O> function){
  checkNotNull(future);
  checkNotNull(function);
  return new Future<O>(){
    private final Object lock=new Object();
    private boolean set=false;
    private O value=null;
    @Override public O get() throws InterruptedException, ExecutionException {
      return apply(future.get());
    }
    @Override public O get(    long timeout,    TimeUnit unit) throws InterruptedException, ExecutionException, TimeoutException {
      return apply(future.get(timeout,unit));
    }
    private O apply(    I raw){
synchronized (lock) {
        if (!set) {
          value=function.apply(raw);
          set=true;
        }
        return value;
      }
    }
    @Override public boolean cancel(    boolean mayInterruptIfRunning){
      return future.cancel(mayInterruptIfRunning);
    }
    @Override public boolean isCancelled(){
      return future.isCancelled();
    }
    @Override public boolean isDone(){
      return future.isDone();
    }
  }
;
}
